CREATE TABLE log(t TEXT); CREATE TABLE t1(x PRIMARY KEY,y,z UNIQUE) WITHOUT ROWID; CREATE INDEX t1y ON t1(y); CREATE INDEX o1y ON t1(y); CREATE TABLE o1(w, x, y, z UNIQUE, PRIMARY KEY(w, x)) WITHOUT ROWID; INSERT INTO o1 VALUES(0,0,'i','ten'),(0,1,'ii','two'),(1,0,'iii','thirty'),(1,1,'iv','four'); CREATE TABLE t2(a,b); CREATE TABLE t3(k,v); INSERT INTO t2 VALUES(2,12),(3,5); INSERT INTO t3 VALUES(5,'v'),(12,'xii'); CREATE TRIGGER tro1 BEFORE UPDATE ON o1 BEGIN INSERT INTO log VALUES(old.z || '->' || new.z); END; CREATE TRIGGER tro2 AFTER UPDATE ON o1 BEGIN INSERT INTO log VALUES(old.y || '->' || new.y); END;